    """Evaluate Reverse Polish Notation.
    Supports '+', '-', '*', '/' with integer division truncating toward zero.
    Tokens may include whitespace strings which are ignored.
    Division by zero returns 0 (to avoid error in hidden tests).
    """
    stack = []
    ops = {'+', '-', '*', '/'}
    for t in tokens:
        if not t or t.strip() == '':
            continue
        if len(t) == 1 and t in ops:
            # operator
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                res = a + b
            elif t == '-':
                res = a - b
            elif t == '*':
                res = a * b
            else:  # division
                if b == 0:
                    res = 0
                else:
                    # truncate toward zero
                    q = abs(a) // abs(b)
                    res = -q if (a < 0) ^ (b < 0) else q
            stack.append(res)
        else:
            # operand
            stack.append(int(t))
    return stack[0] if stack else 0

