def solve(grid):
    # Handle empty grid
    if not grid:
        return 0
    n = len(grid)
    # Determine max columns to handle jagged rows
    m = max((len(row) for row in grid), default=0)
    visited = [[False]*m for _ in range(n)]
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if x < 0 or x >= n or y < 0:
                continue
            if y >= len(grid[x]):
                continue
            if visited[x][y] or grid[x][y] != 1:
                continue
            visited[x][y] = True
            stack.extend([(x-1, y), (x+1, y), (x, y-1), (x, y+1)])
    count = 0
    for i in range(n):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and not visited[i][j]:
                count += 1
                dfs(i, j)
    return count

def solve(s):
    """Run-length encoding for a sequence.
    Accepts any iterable (string, list, tuple, bytes). Non-iterable returns empty list.
    Returns list of [element, count] pairs.
    """
    try:
        seq = list(s)
    except TypeError:
        return []
    if not seq:
        return []
    result = []
    prev = seq[0]
    count = 1
    for ch in seq[1:]:
        if ch == prev:
            count += 1
        else:
            result.append([prev, count])
            prev = ch
            count = 1
    result.append([prev, count])
    return result

