def solve(tokens):
    """Evaluate Reverse Polish Notation.
    Supports tokens as strings or integers. Division truncates toward zero.
    If division by zero occurs, returns 0.
    """
    if not tokens:
        return 0
    stack = []
    ops = {'+', '-', '*', '/'}
    for tok in tokens:
        if tok in ops:
            if len(stack) < 2:
                return 0
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # '/'
                if b == 0:
                    return 0
                # Truncate toward zero
                res = int(a / b)
            stack.append(res)
        else:
            # token may be int or numeric string
            try:
                stack.append(int(tok))
            except Exception:
                # Non-numeric token, ignore or treat as 0
                stack.append(0)
    return stack[-1] if stack else 0

