def solve(tokens):
    """Evaluate Reverse Polish Notation (batch 2) robustly.
    tokens: iterable of tokens, each token may be an int, or a string representing an integer or an operator '+', '-', '*', '/'.
    Empty strings or whitespace-only tokens are ignored.
    Division truncates toward zero.
    Returns the integer result, or 0 for empty input.
    """
    if not tokens:
        return 0
    stack = []
    ops = {'+', '-', '*', '/'}
    for t in tokens:
        # Normalise token to string if not int
        if isinstance(t, int):
            stack.append(t)
            continue
        if not isinstance(t, str):
            # Try to convert to int
            try:
                stack.append(int(t))
                continue
            except Exception:
                continue
        token = t.strip()
        if token == '':
            continue
        if token in ops:
            if len(stack) < 2:
                raise ValueError('Insufficient operands')
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # division trunc towards zero
                # Handle division by zero gracefully: return 0
                if b == 0:
                    stack.append(0)
                else:
                    stack.append(int(a / b))
        else:
            # operand token
            try:
                stack.append(int(token))
            except ValueError:
                # ignore non‑numeric token
                continue
    return stack[0] if stack else 0

